#pragma once#include "SignalTags.h"class KAnalogVariable : public KSignalTag{public:  KAnalogVariable();  KAnalogVariable( LPCSTR pUnits, int num );  KAnalogVariable( std::vector<std::string> &params );  virtual LPCSTR GetType() const  {    return "AnalogVariable";  }  virtual bool IsAnalog()  {    return true;  }  virtual LPCSTR GetOnLabel()  {    return NULL;  }  virtual LPCSTR GetOffLabel()  {    return NULL;  }};//////////////////////////////////////////////////////////////////////////class KDigitalVariable : public KSignalTag{public:  KDigitalVariable();  KDigitalVariable( std::vector<std::string> &params );  void SetOnLabel( LPCSTR pszV )  {    szOn = pszV;  }  void SetOffLabel( LPCSTR pszV )  {    szOff = pszV;  }protected:  virtual LPCSTR GetType() const  {    return "DigitalVariable";  }  virtual bool IsAnalog()  {    return false;  }  virtual LPCSTR GetOnLabel()  {    return szOn.c_str();  }  virtual LPCSTR GetOffLabel()  {    return szOff.c_str();  }protected:  std::string szOn, szOff;};